Method.Source:
/// <summary>
/// Initializes a SalesParmTable record.
/// </summary>
/// <param name = "_salesTable">The SalesTable record.</param>
/// <param name = "_salesLine">The SalesLine record.</param>
/// <param name = "_tableRefId">The TradeLineRefId value.</param>
/// <param name = "_postingProfile">The CustPostingProfile value.</param>
/// <param name = "_inventProfileType">The InventProfileType_RU value.</param>
/// <param name = "_inventOwnerId">The InventOwnerId_RU value.</param>
/// <param name = "_mcrPackingBoxName">The MCRPackingBoxName value.</param>
/// <returns>The initialized SalesParmTable record.</returns>
protected SalesParmTable initParmTable(SalesTable _salesTable, Common _salesLine, TradeLineRefId _tableRefId, CustPostingProfile _postingProfile, InventProfileType_RU _inventProfileType, InventOwnerId_RU _inventOwnerId, MCRPackingBoxName _mcrPackingBoxName)
{
    SalesParmTable ret;

    ret = next initParmTable(_salesTable, _salesLine, _tableRefId, _postingProfile, _inventProfileType, _inventOwnerId, _mcrPackingBoxName);

    ret.FixedDueDate = this.metUpdateFixedDueDate(_salesTable, ret).FixedDueDate;

    return ret;
}

/// <summary>
/// Update the FixedDueDate field in the SalesParmTable based on the ExtendedTerms settings in the METSalesTable.
/// </summary>
/// <param name = "_salesTable">The SalesTable record.</param>
/// <param name = "_salesParmTable">The SalesParmTable record.</param>
/// <returns>The updated SalesParmTable record.</returns>
public SalesParmTable metUpdateFixedDueDate(SalesTable _salesTable, SalesParmTable  _salesParmTable)
{
    METSalesTable metSalesTable = _salesTable.metSalesTable();

    if (metSalesTable && metSalesTable.ExtendedTerms)
    {
        if (metSalesTable.ExtendedTermsMethod == METExtendedTermsMethod::InvoiceDueDate)
        {
            _salesParmTable.FixedDueDate = metSalesTable.ExtendedDate;
        }
        else if (metSalesTable.ExtendedTermsMethod == METExtendedTermsMethod::ExtendedDays)
        {
            utcdatetime convertedDateTime;

            TransDate paymDueDateCalc = _salesTable.payment().due(_salesParmTable.Transdate ? _salesParmTable.Transdate  : today());
            convertedDateTime = DateTimeUtil::newDateTime(paymDueDateCalc, 0, DateTimeUtil::getUserPreferredTimeZone());

            convertedDateTime = DateTimeUtil::addDays(convertedDateTime, metSalesTable.ExtendedDays);
            _salesParmTable.FixedDueDate = DateTimeUtil::date(convertedDateTime);
        }
    }

    return _salesParmTable;
}
